class Parser(HTMLParser):
 def __init__(self):super().__init__();self.on=False;self.p=[];self.buf=[]
 def handle_starttag(self,t,a):
  if t=='p':self.on=True;self.buf=[]
 def handle_data(self,d):
  if self.on:self.buf.append(d)
 def handle_endtag(self,t):
  if t=='p' and self.on:self.p.append(' '.join(''.join(self.buf).split()));self.on=False
z=Parser();z.feed(Path('/workspace/scratch/e27e3582e197/annotation-research/base.html').read_text());F={}
